mapper.select:
SELECT record.id, record.category_id, category.category_name, record.expense_amount, record.expense_date, record.expense_type, record.remark, record.create_time, record.update_time FROM daily_expense_record record LEFT JOIN base_tally_category category ON record.category_id = category.id WHERE record.del_flag = 0
AND record.expense_date BETWEEN #{vo.startDate} AND #{vo.endDate}
ORDER BY record.expense_date DESC, record.id ASC
